result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "perceptron.py", "content": """"Classic and averaged perceptron (numpy) with self-tests."""
import numpy as np


def make_data(n_per_class=300, centers=((-2.0, -2.0), (2.0, 2.0)), std=0.5, seed=9):
    rng = np.random.default_rng(seed)
    X = np.vstack([rng.normal(loc=c, scale=std, size=(n_per_class, 2)) for c in centers])
    y = np.hstack([np.full(n_per_class, 1), np.full(n_per_class, -1)])
    return X, y


class Perceptron:
    """Classic perceptron. Labels in {-1, +1}."""

    def __init__(self, n_features):
        self.w = np.zeros(n_features)
        self.b = 0.0
        self.mistakes_per_epoch = []

    def fit(self, X, y, max_epochs=100):
        X = np.asarray(X, dtype=float)
        y = np.asarray(y, dtype=float)
        for _ in range(max_epochs):
            mistakes = 0
            for xi, yi in zip(X, y):
                if yi * (self.w @ xi + self.b) <= 0:
                    self.w += yi * xi
                    self.b += yi
                    mistakes += 1
            self.mistakes_per_epoch.append(mistakes)
            if mistakes == 0:
                break
        return self

    def predict(self, X):
        return np.where(np.asarray(X, float) @ self.w + self.b > 0, 1, -1)

    def score(self, X, y):
        return float(np.mean(self.predict(X) == y))


class AveragedPerceptron:
    """Averaged perceptron (Freund & Schapire). Tracks running average of weights."""

    def __init__(self, n_features):
        self.w = np.zeros(n_features)
        self.b = 0.0
        self.w_avg = np.zeros(n_features)
        self.b_avg = 0.0
        self.count = 1  # denominator for the average (start at 1 to avoid div by zero)
        self.mistakes_per_epoch = []

    def _update_avg(self):
        self.w_avg += self.w
        self.b_avg += self.b
        self.count += 1

    def fit(self, X, y, max_epochs=100):
        X = np.asarray(X, dtype=float)
        y = np.asarray(y, dtype=float)
        for _ in range(max_epochs):
            mistakes = 0
            for xi, yi in zip(X, y):
                if yi * (self.w @ xi + self.b) <= 0:
                    self.w += yi * xi
                    self.b += yi
                    mistakes += 1
                else:
                    self._update_avg()
            self.mistakes_per_epoch.append(mistakes)
            if mistakes == 0:
                # flush remaining updates so the average reflects convergence
                for __ in range(10):
                    self._update_avg()
                break
        self.w_avg /= self.count
        self.b_avg /= self.count
        return self

    def predict(self, X):
        return np.where(np.asarray(X, float) @ self.w_avg + self.b_avg > 0, 1, -1)

    def score(self, X, y):
        return float(np.mean(self.predict(X) == y))


def run_tests():
    X_train, y_train = make_data()
    X_test, y_test = make_data(seed=9127)

    # Test 1: classic perceptron reaches 100% training accuracy within 20 epochs.
    p = Perceptron(X_train.shape[1]).fit(X_train, y_train, max_epochs=20)
    assert len(p.mistakes_per_epoch) <= 20
    assert p.score(X_train, y_train) == 1.0, f"train acc {p.score(X_train, y_train)}"

    # Test 2: averaged perceptron test accuracy >= 0.99 on fresh sample.
    ap = AveragedPerceptron(X_train.shape[1]).fit(X_train, y_train, max_epochs=20)
    test_acc = ap.score(X_test, y_test)
    assert test_acc >= 0.99, f"test acc {test_acc}"

    # Test 3: mistake count per epoch non-increasing after epoch 5.
    m = p.mistakes_per_epoch
    tail = m[4:]  # epochs 5.. onward (1-indexed epoch 5 is index 4)
    assert all(a >= b for a, b in zip(tail, tail[1:])), f"mistakes not non-increasing: {m}"

    print(f"classic: {len(m)} epochs, mistakes/epoch={m}, train acc={p.score(X_train, y_train):.4f}")
    print(f"averaged: {len(ap.mistakes_per_epoch)} epochs, mistakes/epoch={ap.mistakes_per_epoch}, "
          f"test acc={test_acc:.4f}")
    print("All tests passed.")


if __name__ == "__main__":
    run_tests()
